import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] counts = new int[1000001];
        for (int i = 0; i < n; i++) counts[nextInt()]++;
        int k = 0;
        long[] frequencies = new long[n];
        for (int c : counts)
            if (c > 0) frequencies[k++] = c;
        long smallest = Long.MAX_VALUE;
        for (int i = 0; i < k; i++) smallest = Math.min(smallest, frequencies[i]);
        // Try group sizes b / b+1 from the largest b down; the first feasible b is optimal.
        for (long b = smallest; b >= 1; b--) {
            long answer = 0;
            boolean ok = true;
            for (int i = 0; i < k; i++) {
                long groups = (frequencies[i] + b) / (b + 1);
                if (groups * b > frequencies[i]) {
                    ok = false;
                    break;
                }
                answer += groups;
            }
            if (ok) {
                System.out.println(answer);
                return;
            }
        }
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	counts := make([]int, 1000001)
	for i := 0; i < n; i++ {
		counts[nextInt()]++
	}
	frequencies := []int{}
	smallest := n
	for _, c := range counts {
		if c > 0 {
			frequencies = append(frequencies, c)
			smallest = min(smallest, c)
		}
	}
	// Try group sizes b / b+1 from the largest b down; the first feasible b is optimal.
	for b := smallest; b >= 1; b-- {
		answer, ok := 0, true
		for _, f := range frequencies {
			groups := (f + b) / (b + 1)
			if groups*b > f {
				ok = false
				break
			}
			answer += groups
		}
		if ok {
			fmt.Println(answer)
			return
		}
	}
}
